insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (31, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'らいねん だいがくを <u>卒業します</u>。', '["そつぎょうします","にゅうがくします","しゅっせきします","きゅうけいします"]'::jsonb, 0, '卒業します dibaca “そつぎょうします” dan berarti lulus (universitas).', 'Bab 31–35 · Mondai 1 No.1', 'kanji:卒業します'),
  (31, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しけんを <u>受けます</u>。', '["うけます","つづけます","はじまります","みつけます"]'::jsonb, 0, '受けます dibaca “うけます” dan berarti menempuh (ujian).', 'Bab 31–35 · Mondai 1 No.2', 'kanji:受けます'),
  (31, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この こうえんは とても <u>美しい</u>です。', '["うつくしい","ふつうの","じゆうに","あたらしい"]'::jsonb, 0, '美しい dibaca “うつくしい” dan berarti indah.', 'Bab 31–35 · Mondai 1 No.3', 'kanji:美しい'),
  (31, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あしたは <u>晴れます</u>。', '["はれます","くもります","つづきます","もどります"]'::jsonb, 0, '晴れます dibaca “はれます” dan berarti menjadi cerah.', 'Bab 31–35 · Mondai 1 No.4', 'kanji:晴れます'),
  (31, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょうきが <u>治ります</u>。', '["なおります","つづきます","はれます","もどります"]'::jsonb, 0, '治ります dibaca “なおります” dan berarti sembuh.', 'Bab 31–35 · Mondai 1 No.5', 'kanji:治ります'),
  (31, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>健康</u>に きを つけます。', '["けんこう","てんき","たいふう","しつど"]'::jsonb, 0, '健康 dibaca “けんこう” dan berarti kesehatan.', 'Bab 31–35 · Mondai 1 No.6', 'kanji:健康'),
  (31, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きけんですから <u>注意します</u>。', '["ちゅういします","はずします","つたえます","まもります"]'::jsonb, 0, '注意します dibaca “ちゅういします” dan berarti memperhatikan/berhati-hati.', 'Bab 31–35 · Mondai 1 No.7', 'kanji:注意します'),
  (31, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きそくを <u>守ります</u>。', '["まもります","つたえます","あげます","さげます"]'::jsonb, 0, '守ります dibaca “まもります” dan berarti mematuhi.', 'Bab 31–35 · Mondai 1 No.8', 'kanji:守ります'),
  (31, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はを <u>磨きます</u>。', '["みがきます","おります","のせます","つけます"]'::jsonb, 0, '磨きます dibaca “みがきます” dan berarti menggosok (gigi).', 'Bab 31–35 · Mondai 1 No.9', 'kanji:磨きます'),
  (31, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かみを <u>折ります</u>。', '["おります","みがきます","くみたてます","のせます"]'::jsonb, 0, '折ります dibaca “おります” dan berarti melipat.', 'Bab 31–35 · Mondai 1 No.10', 'kanji:折ります'),
  (31, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'だいがくに <u>にゅうがくします</u>。', '["入学します","卒業します","出席します","休憩します"]'::jsonb, 0, 'にゅうがくします ditulis 入学します, berarti masuk universitas.', 'Bab 31–35 · Mondai 2 No.11', 'kanji:入学します'),
  (31, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもたちが こうえんに <u>あつまります</u>。', '["集まります","残ります","閉じます","始まります"]'::jsonb, 0, 'あつまります ditulis 集まります, berarti berkumpul.', 'Bab 31–35 · Mondai 2 No.12', 'kanji:集まります'),
  (31, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'むすこの けんこうが <u>しんぱいです</u>。', '["心配","無理","十分","健康"]'::jsonb, 0, 'しんぱい ditulis 心配, berarti khawatir.', 'Bab 31–35 · Mondai 2 No.13', 'kanji:心配'),
  (31, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんわで にゅーすを <u>つたえます</u>。', '["伝えます","注意します","守ります","外します"]'::jsonb, 0, 'つたえます ditulis 伝えます, berarti menyampaikan.', 'Bab 31–35 · Mondai 2 No.14', 'kanji:伝えます'),
  (31, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せきを <u>はずします</u>。', '["外します","伝えます","注意します","守ります"]'::jsonb, 0, 'はずします ditulis 外します, berarti sedang tidak di tempat.', 'Bab 31–35 · Mondai 2 No.15', 'kanji:外します'),
  (31, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この せんは とても <u>ほそい</u>です。', '["細い","太い","黒い","白い"]'::jsonb, 0, 'ほそい ditulis 細い, berarti tipis/kurus.', 'Bab 31–35 · Mondai 2 No.16', 'kanji:細い'),
  (31, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この さかなは とても <u>めずらしい</u>です。', '["珍しい","正しい","楽な","必要な"]'::jsonb, 0, 'めずらしい ditulis 珍しい, berarti langka/aneh.', 'Bab 31–35 · Mondai 2 No.17', 'kanji:珍しい'),
  (31, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この こたえは <u>ただしい</u>です。', '["正しい","珍しい","楽な","必要な"]'::jsonb, 0, 'ただしい ditulis 正しい, berarti benar.', 'Bab 31–35 · Mondai 2 No.18', 'kanji:正しい'),
  (31, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はなが <u>さきます</u>。', '["咲きます","困ります","拾います","付けます"]'::jsonb, 0, 'さきます ditulis 咲きます, berarti mekar (bunga).', 'Bab 31–35 · Mondai 2 No.19', 'kanji:咲きます'),
  (31, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しんごうが あおに <u>かわります</u>。', '["変わります","咲きます","困ります","拾います"]'::jsonb, 0, 'かわります ditulis 変わります, berarti berubah.', 'Bab 31–35 · Mondai 2 No.20', 'kanji:変わります'),
  (31, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>らいねん</span><span class="arrange-chip"><b>②</b>つもりです。</span><span class="arrange-chip"><b>③</b>にほん</span><span class="arrange-chip"><b>④</b>いく</span><span class="arrange-chip"><b>⑤</b>へ</span></div><small>Petunjuk arti: “Tahun depan saya berniat pergi ke Jepang.”</small>', '["①→③→⑤→④→②","③→①→⑤→④→②","①→⑤→③→④→②","①→③→④→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ①らいねん→③にほん→⑤へ→④いく→②つもりです。 へ menandai arah/tujuan sebelum kata kerja いく, dipakai bersama ～つもりです (Pel.31).', 'Bab 31–35 · Mondai 3 No.21', 'materi:book2:5:0'),
  (31, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>から</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>よてい</span><span class="arrange-chip"><b>⑤</b>です。</span><span class="arrange-chip"><b>⑥</b>3じ</span><span class="arrange-chip"><b>⑦</b>かいぎ</span></div><small>Petunjuk arti: “Rapat dijadwalkan mulai jam tiga.”</small>', '["⑦→②→⑥→①→③→④→⑤","②→⑦→⑥→①→③→④→⑤","⑦→⑥→②→①→③→④→⑤","⑦→②→①→⑥→③→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ⑦かいぎ→②は→⑥3じ→①から→③の→④よてい→⑤です。 から menandai titik mulai waktu, dipasangkan dengan の untuk membentuk predikat ～のよていです (Pel.31).', 'Bab 31–35 · Mondai 3 No.22', 'materi:book2:5:0'),
  (31, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>たべた</span><span class="arrange-chip"><b>③</b>ほうが</span><span class="arrange-chip"><b>④</b>やさい</span><span class="arrange-chip"><b>⑤</b>いいです。</span><span class="arrange-chip"><b>⑥</b>もっと</span></div><small>Petunjuk arti: “Sebaiknya makan lebih banyak sayur.”</small>', '["⑥→④→①→②→③→⑤","④→⑥→①→②→③→⑤","⑥→①→④→②→③→⑤","⑥→④→②→①→③→⑤"]'::jsonb, 0, 'Urutan yang benar: ⑥もっと→④やさい→①を→②たべた→③ほうが→⑤いいです。 を menandai objek sebelum Kata Kerja bentuk たほうがいいです (Pel.32).', 'Bab 31–35 · Mondai 3 No.23', 'materi:book2:6:0'),
  (31, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>にもつ</span><span class="arrange-chip"><b>③</b>もちましょうか。</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Bolehkah saya membawakan barangnya?”</small>', '["①→④→②→⑤→③","④→①→②→⑤→③","①→②→④→⑤→③","①→④→⑤→②→③"]'::jsonb, 0, 'Urutan yang benar: ①わたし→④が→②にもつ→⑤を→③もちましょうか。 が menegaskan pembicara sendiri sebagai pelaku yang menawarkan bantuan, sebelum Kata Kerjaましょうか (Pel.32).', 'Bab 31–35 · Mondai 3 No.24', 'materi:book2:6:0'),
  (31, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>と</span><span class="arrange-chip"><b>②</b>いう</span><span class="arrange-chip"><b>③</b>たちいりきんし</span><span class="arrange-chip"><b>④</b>はいるな</span><span class="arrange-chip"><b>⑤</b>いみです。</span><span class="arrange-chip"><b>⑥</b>は</span></div><small>Petunjuk arti: “Dilarang masuk berarti jangan masuk.”</small>', '["③→⑥→④→①→②→⑤","⑥→③→④→①→②→⑤","③→④→⑥→①→②→⑤","③→⑥→①→④→②→⑤"]'::jsonb, 0, 'Urutan yang benar: ③たちいりきんし→⑥は→④はいるな→①と→②いう→⑤いみです。 と menandai isi kutipan sebelum いう dalam pola ～という意味です untuk menjelaskan arti (Pel.33).', 'Bab 31–35 · Mondai 3 No.25', 'materi:book2:7:0'),
  (31, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ぬいで</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>はいってください。</span><span class="arrange-chip"><b>④</b>くつ</span></div><small>Petunjuk arti: “Lepaskan sepatu lalu silakan masuk.”</small>', '["④→②→①→③","②→④→①→③","④→①→②→③","④→②→③→①"]'::jsonb, 0, 'Urutan yang benar: ④くつ→②を→①ぬいで→③はいってください。 を menandai objek sebelum Kata Kerja bentuk て yang menjelaskan cara/keadaan (Pel.34).', 'Bab 31–35 · Mondai 3 No.26', 'materi:book2:8:0'),
  (31, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>してください。</span><span class="arrange-chip"><b>③</b>とおりに</span><span class="arrange-chip"><b>④</b>せつめいしょ</span></div><small>Petunjuk arti: “Tolong lakukan sesuai petunjuk.”</small>', '["④→①→③→②","①→④→③→②","④→③→①→②","④→①→②→③"]'::jsonb, 0, 'Urutan yang benar: ④せつめいしょ→①の→③とおりに→②してください。 の menghubungkan kata benda dengan とおりに untuk menyatakan “sesuai dengan” (Pel.34).', 'Bab 31–35 · Mondai 3 No.27', 'materi:book2:8:0'),
  (31, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>あれば</span><span class="arrange-chip"><b>③</b>じかん</span><span class="arrange-chip"><b>④</b>いきます。</span></div><small>Petunjuk arti: “Kalau ada waktu, saya pergi.”</small>', '["③→①→②→④","①→③→②→④","③→②→①→④","③→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③じかん→①が→②あれば→④いきます。 が menandai subjek sebelum Kata Kerja bentuk ば yang menyatakan syarat umum (Pel.35).', 'Bab 31–35 · Mondai 3 No.28', 'materi:book2:9:0'),
  (31, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いいです。</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>はる</span><span class="arrange-chip"><b>④</b>へ</span><span class="arrange-chip"><b>⑤</b>きょうと</span><span class="arrange-chip"><b>⑥</b>なら</span><span class="arrange-chip"><b>⑦</b>いく</span></div><small>Petunjuk arti: “Kalau pergi ke Kyoto, musim semi bagus.”</small>', '["⑤→④→⑦→⑥→③→②→①","④→⑤→⑦→⑥→③→②→①","⑤→⑦→④→⑥→③→②→①","⑤→④→⑥→⑦→③→②→①"]'::jsonb, 0, 'Urutan yang benar: ⑤きょうと→④へ→⑦いく→⑥なら→③はる→②が→①いいです。 へ menandai tujuan sebelum なら, yang menyatakan saran berdasarkan topik yang disebut lawan bicara (Pel.35).', 'Bab 31–35 · Mondai 3 No.29', 'materi:book2:9:0'),
  (31, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あめ</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>いきます。</span><span class="arrange-chip"><b>④</b>ふっても</span></div><small>Petunjuk arti: “Walaupun hujan, saya pergi.”</small>', '["①→②→④→③","②→①→④→③","①→④→②→③","①→②→③→④"]'::jsonb, 0, 'Urutan yang benar: ①あめ→②が→④ふっても→③いきます。 が menandai subjek sebelum Kata Kerja bentuk ても yang menyatakan hasil tetap berlaku (Pel.35).', 'Bab 31–35 · Mondai 3 No.30', 'materi:book2:9:0'),
  (31, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょう</span><span class="arrange-chip"><b>②</b>でかけない</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>つもりです。</span></div><small>Petunjuk arti: “Hari ini saya berniat tidak keluar.”</small>', '["①→③→②→④","③→①→②→④","①→②→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①きょう→③は→②でかけない→④つもりです。 Bentuk ない dipakai sebelum つもりです untuk menyatakan niat TIDAK melakukan sesuatu (Pel.31).', 'Bab 31–35 · Mondai 4 No.31', 'materi:book2:5:0'),
  (31, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>ほうが</span><span class="arrange-chip"><b>③</b>いいです。</span><span class="arrange-chip"><b>④</b>おさけ</span><span class="arrange-chip"><b>⑤</b>のみすぎない</span></div><small>Petunjuk arti: “Sebaiknya jangan terlalu banyak minum alkohol.”</small>', '["④→①→⑤→②→③","①→④→⑤→②→③","④→⑤→①→②→③","④→①→②→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ④おさけ→①を→⑤のみすぎない→②ほうが→③いいです。 Kata Kerja bentuk ないほうがいいです menyatakan saran agar TIDAK melakukan sesuatu (Pel.32).', 'Bab 31–35 · Mondai 4 No.32', 'materi:book2:6:0'),
  (31, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>たばこ</span><span class="arrange-chip"><b>②</b>いみです。</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>いけない</span><span class="arrange-chip"><b>⑥</b>で</span><span class="arrange-chip"><b>⑦</b>という</span><span class="arrange-chip"><b>⑧</b>ここ</span><span class="arrange-chip"><b>⑨</b>すっては</span></div><small>Petunjuk arti: “Di sini artinya tidak boleh merokok.”</small>', '["⑧→⑥→④→①→③→⑨→⑤→⑦→②","⑥→⑧→④→①→③→⑨→⑤→⑦→②","⑧→④→⑥→①→③→⑨→⑤→⑦→②","⑧→⑥→①→④→③→⑨→⑤→⑦→②"]'::jsonb, 0, 'Urutan yang benar: ⑧ここ→⑥で→④は→①たばこ→③を→⑨すっては→⑤いけない→⑦という→②いみです。 Pola ～という意味です dipakai untuk menjelaskan arti dari suatu aturan atau larangan yang disebut sebelumnya (Pel.33).', 'Bab 31–35 · Mondai 4 No.33', 'materi:book2:7:0'),
  (31, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ごはん</span><span class="arrange-chip"><b>②</b>あとで</span><span class="arrange-chip"><b>③</b>べんきょうします。</span><span class="arrange-chip"><b>④</b>たべた</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Setelah makan, saya belajar.”</small>', '["①→⑤→④→②→③","⑤→①→④→②→③","①→④→⑤→②→③","①→⑤→②→④→③"]'::jsonb, 0, 'Urutan yang benar: ①ごはん→⑤を→④たべた→②あとで→③べんきょうします。 Kata Kerja bentuk たあとで menyatakan tindakan yang dilakukan SETELAH tindakan lain selesai (Pel.34).', 'Bab 31–35 · Mondai 4 No.34', 'materi:book2:8:0'),
  (31, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほうが</span><span class="arrange-chip"><b>②</b>よやくした</span><span class="arrange-chip"><b>③</b>はやく</span><span class="arrange-chip"><b>④</b>する</span><span class="arrange-chip"><b>⑤</b>りょこう</span><span class="arrange-chip"><b>⑥</b>なら</span><span class="arrange-chip"><b>⑦</b>いいです。</span></div><small>Petunjuk arti: “Kalau mau bepergian, sebaiknya cepat memesan.”</small>', '["⑤→④→⑥→③→②→①→⑦","④→⑤→⑥→③→②→①→⑦","⑤→⑥→④→③→②→①→⑦","⑤→④→③→⑥→②→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤りょこう→④する→⑥なら→③はやく→②よやくした→①ほうが→⑦いいです。 なら menyatakan saran berdasarkan topik yang disebut lawan bicara, diikuti pola たほうがいいです (Pel.35).', 'Bab 31–35 · Mondai 4 No.35', 'materi:book2:9:0'),
  (31, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'らいねん、にほんへ　りゅうがくする　つもりです。りょこうの　ひは、らいげつの　15にちの　よていです。<br><small>「よていです」は、どちらの　ことですか。</small>', '["りゅうがくすること","りょこうのひ","にほんへいくこと","らいねんのこと"]'::jsonb, 1, '予定です menyatakan RENCANA/JADWAL OBJEKTIF yang sudah ditentukan (tanggal perjalanan), berbeda dari つもりです yang menyatakan NIAT PRIBADI (rencana studi ke luar negeri) (Pel.31).', 'Bab 31–35 · Soal Cerita No.36', 'materi:book2:5:0'),
  (31, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'やさいを　もっと　たべた　ほうが　いいです。でも、おさけを　のみすぎない　ほうが　いいです。<br><small>すすめられている　ことは、なんですか。</small>', '["やさいをたべること","おさけをのむこと","おさけをのみすぎること","なにもたべないこと"]'::jsonb, 0, 'たほうがいいです menyarankan MELAKUKAN sesuatu (makan sayur), sedangkan ないほうがいいです menyarankan TIDAK melakukan (jangan minum berlebihan) — dua arah saran yang berlawanan (Pel.32).', 'Bab 31–35 · Soal Cerita No.37', 'materi:book2:6:0'),
  (31, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '「たちいりきんし」という　かんばんが　あります。これは「はいるな」という　いみです。<br><small>「たちいりきんし」は、なにを　しては　いけないという　いみですか。</small>', '["でること","はいること","とまること","みること"]'::jsonb, 1, '「立入禁止」berarti「入るな」(jangan masuk), bentuk larangan tegas Bentuk Kamus＋な, dijelaskan dengan pola という意味です (Pel.33).', 'Bab 31–35 · Soal Cerita No.38', 'materi:book2:7:0'),
  (31, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'はを　みがいた　あとで、ねます。せつめいしょの　とおりに、きかいを　くみたてます。<br><small>「とおりに」は、なにを　あらわしますか。</small>', '["じゅんばん（はやい・おそい）","ほうほう（どうやってするか）","じかん（いつするか）","ばしょ（どこでするか）"]'::jsonb, 1, 'とおりに menyatakan melakukan sesuatu SESUAI CONTOH/PETUNJUK (cara), berbeda dari あとで yang menyatakan URUTAN WAKTU (Pel.34).', 'Bab 31–35 · Soal Cerita No.39', 'materi:book2:8:0'),
  (31, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'じかんが　あれば、いきます。きょうとへ　いくなら、はるが　いいです。あめが　ふっても、いきます。<br><small>あめの　ひでも、いきますか。</small>', '["はい、いきます","いいえ、いきません","じかんがあれば、いきます","はるなら、いきます"]'::jsonb, 0, '「あめがふっても、いきます」menggunakan ても yang menyatakan hasil TETAP TERJADI meski syarat (hujan) terpenuhi, jadi jawabannya tetap pergi walau hujan (Pel.35).', 'Bab 31–35 · Soal Cerita No.40', 'materi:book2:9:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (31, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'らいねん だいがくを <u>卒業します</u>。', '["そつぎょうします","にゅうがくします","しゅっせきします","きゅうけいします"]'::jsonb, 0, '卒業します dibaca “そつぎょうします” dan berarti lulus (universitas).', 'Bab 31–35 · Mondai 1 No.1', 'kanji:卒業します'),
  (31, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しけんを <u>受けます</u>。', '["うけます","つづけます","はじまります","みつけます"]'::jsonb, 0, '受けます dibaca “うけます” dan berarti menempuh (ujian).', 'Bab 31–35 · Mondai 1 No.2', 'kanji:受けます'),
  (31, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この こうえんは とても <u>美しい</u>です。', '["うつくしい","ふつうの","じゆうに","あたらしい"]'::jsonb, 0, '美しい dibaca “うつくしい” dan berarti indah.', 'Bab 31–35 · Mondai 1 No.3', 'kanji:美しい'),
  (31, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あしたは <u>晴れます</u>。', '["はれます","くもります","つづきます","もどります"]'::jsonb, 0, '晴れます dibaca “はれます” dan berarti menjadi cerah.', 'Bab 31–35 · Mondai 1 No.4', 'kanji:晴れます'),
  (31, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'びょうきが <u>治ります</u>。', '["なおります","つづきます","はれます","もどります"]'::jsonb, 0, '治ります dibaca “なおります” dan berarti sembuh.', 'Bab 31–35 · Mondai 1 No.5', 'kanji:治ります'),
  (31, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>健康</u>に きを つけます。', '["けんこう","てんき","たいふう","しつど"]'::jsonb, 0, '健康 dibaca “けんこう” dan berarti kesehatan.', 'Bab 31–35 · Mondai 1 No.6', 'kanji:健康'),
  (31, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きけんですから <u>注意します</u>。', '["ちゅういします","はずします","つたえます","まもります"]'::jsonb, 0, '注意します dibaca “ちゅういします” dan berarti memperhatikan/berhati-hati.', 'Bab 31–35 · Mondai 1 No.7', 'kanji:注意します'),
  (31, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きそくを <u>守ります</u>。', '["まもります","つたえます","あげます","さげます"]'::jsonb, 0, '守ります dibaca “まもります” dan berarti mematuhi.', 'Bab 31–35 · Mondai 1 No.8', 'kanji:守ります'),
  (31, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はを <u>磨きます</u>。', '["みがきます","おります","のせます","つけます"]'::jsonb, 0, '磨きます dibaca “みがきます” dan berarti menggosok (gigi).', 'Bab 31–35 · Mondai 1 No.9', 'kanji:磨きます'),
  (31, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かみを <u>折ります</u>。', '["おります","みがきます","くみたてます","のせます"]'::jsonb, 0, '折ります dibaca “おります” dan berarti melipat.', 'Bab 31–35 · Mondai 1 No.10', 'kanji:折ります'),
  (31, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'だいがくに <u>にゅうがくします</u>。', '["入学します","卒業します","出席します","休憩します"]'::jsonb, 0, 'にゅうがくします ditulis 入学します, berarti masuk universitas.', 'Bab 31–35 · Mondai 2 No.11', 'kanji:入学します'),
  (31, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもたちが こうえんに <u>あつまります</u>。', '["集まります","残ります","閉じます","始まります"]'::jsonb, 0, 'あつまります ditulis 集まります, berarti berkumpul.', 'Bab 31–35 · Mondai 2 No.12', 'kanji:集まります'),
  (31, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'むすこの けんこうが <u>しんぱいです</u>。', '["心配","無理","十分","健康"]'::jsonb, 0, 'しんぱい ditulis 心配, berarti khawatir.', 'Bab 31–35 · Mondai 2 No.13', 'kanji:心配'),
  (31, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんわで にゅーすを <u>つたえます</u>。', '["伝えます","注意します","守ります","外します"]'::jsonb, 0, 'つたえます ditulis 伝えます, berarti menyampaikan.', 'Bab 31–35 · Mondai 2 No.14', 'kanji:伝えます'),
  (31, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せきを <u>はずします</u>。', '["外します","伝えます","注意します","守ります"]'::jsonb, 0, 'はずします ditulis 外します, berarti sedang tidak di tempat.', 'Bab 31–35 · Mondai 2 No.15', 'kanji:外します'),
  (31, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この せんは とても <u>ほそい</u>です。', '["細い","太い","黒い","白い"]'::jsonb, 0, 'ほそい ditulis 細い, berarti tipis/kurus.', 'Bab 31–35 · Mondai 2 No.16', 'kanji:細い'),
  (31, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この さかなは とても <u>めずらしい</u>です。', '["珍しい","正しい","楽な","必要な"]'::jsonb, 0, 'めずらしい ditulis 珍しい, berarti langka/aneh.', 'Bab 31–35 · Mondai 2 No.17', 'kanji:珍しい'),
  (31, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この こたえは <u>ただしい</u>です。', '["正しい","珍しい","楽な","必要な"]'::jsonb, 0, 'ただしい ditulis 正しい, berarti benar.', 'Bab 31–35 · Mondai 2 No.18', 'kanji:正しい'),
  (31, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はなが <u>さきます</u>。', '["咲きます","困ります","拾います","付けます"]'::jsonb, 0, 'さきます ditulis 咲きます, berarti mekar (bunga).', 'Bab 31–35 · Mondai 2 No.19', 'kanji:咲きます'),
  (31, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しんごうが あおに <u>かわります</u>。', '["変わります","咲きます","困ります","拾います"]'::jsonb, 0, 'かわります ditulis 変わります, berarti berubah.', 'Bab 31–35 · Mondai 2 No.20', 'kanji:変わります'),
  (31, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>らいねん</span><span class="arrange-chip"><b>②</b>つもりです。</span><span class="arrange-chip"><b>③</b>にほん</span><span class="arrange-chip"><b>④</b>いく</span><span class="arrange-chip"><b>⑤</b>へ</span></div><small>Petunjuk arti: “Tahun depan saya berniat pergi ke Jepang.”</small>', '["①→③→⑤→④→②","③→①→⑤→④→②","①→⑤→③→④→②","①→③→④→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ①らいねん→③にほん→⑤へ→④いく→②つもりです。 へ menandai arah/tujuan sebelum kata kerja いく, dipakai bersama ～つもりです (Pel.31).', 'Bab 31–35 · Mondai 3 No.21', 'materi:book2:5:0'),
  (31, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>から</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>よてい</span><span class="arrange-chip"><b>⑤</b>です。</span><span class="arrange-chip"><b>⑥</b>3じ</span><span class="arrange-chip"><b>⑦</b>かいぎ</span></div><small>Petunjuk arti: “Rapat dijadwalkan mulai jam tiga.”</small>', '["⑦→②→⑥→①→③→④→⑤","②→⑦→⑥→①→③→④→⑤","⑦→⑥→②→①→③→④→⑤","⑦→②→①→⑥→③→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ⑦かいぎ→②は→⑥3じ→①から→③の→④よてい→⑤です。 から menandai titik mulai waktu, dipasangkan dengan の untuk membentuk predikat ～のよていです (Pel.31).', 'Bab 31–35 · Mondai 3 No.22', 'materi:book2:5:0'),
  (31, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>たべた</span><span class="arrange-chip"><b>③</b>ほうが</span><span class="arrange-chip"><b>④</b>やさい</span><span class="arrange-chip"><b>⑤</b>いいです。</span><span class="arrange-chip"><b>⑥</b>もっと</span></div><small>Petunjuk arti: “Sebaiknya makan lebih banyak sayur.”</small>', '["⑥→④→①→②→③→⑤","④→⑥→①→②→③→⑤","⑥→①→④→②→③→⑤","⑥→④→②→①→③→⑤"]'::jsonb, 0, 'Urutan yang benar: ⑥もっと→④やさい→①を→②たべた→③ほうが→⑤いいです。 を menandai objek sebelum Kata Kerja bentuk たほうがいいです (Pel.32).', 'Bab 31–35 · Mondai 3 No.23', 'materi:book2:6:0'),
  (31, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>にもつ</span><span class="arrange-chip"><b>③</b>もちましょうか。</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Bolehkah saya membawakan barangnya?”</small>', '["①→④→②→⑤→③","④→①→②→⑤→③","①→②→④→⑤→③","①→④→⑤→②→③"]'::jsonb, 0, 'Urutan yang benar: ①わたし→④が→②にもつ→⑤を→③もちましょうか。 が menegaskan pembicara sendiri sebagai pelaku yang menawarkan bantuan, sebelum Kata Kerjaましょうか (Pel.32).', 'Bab 31–35 · Mondai 3 No.24', 'materi:book2:6:0'),
  (31, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>と</span><span class="arrange-chip"><b>②</b>いう</span><span class="arrange-chip"><b>③</b>たちいりきんし</span><span class="arrange-chip"><b>④</b>はいるな</span><span class="arrange-chip"><b>⑤</b>いみです。</span><span class="arrange-chip"><b>⑥</b>は</span></div><small>Petunjuk arti: “Dilarang masuk berarti jangan masuk.”</small>', '["③→⑥→④→①→②→⑤","⑥→③→④→①→②→⑤","③→④→⑥→①→②→⑤","③→⑥→①→④→②→⑤"]'::jsonb, 0, 'Urutan yang benar: ③たちいりきんし→⑥は→④はいるな→①と→②いう→⑤いみです。 と menandai isi kutipan sebelum いう dalam pola ～という意味です untuk menjelaskan arti (Pel.33).', 'Bab 31–35 · Mondai 3 No.25', 'materi:book2:7:0'),
  (31, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ぬいで</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>はいってください。</span><span class="arrange-chip"><b>④</b>くつ</span></div><small>Petunjuk arti: “Lepaskan sepatu lalu silakan masuk.”</small>', '["④→②→①→③","②→④→①→③","④→①→②→③","④→②→③→①"]'::jsonb, 0, 'Urutan yang benar: ④くつ→②を→①ぬいで→③はいってください。 を menandai objek sebelum Kata Kerja bentuk て yang menjelaskan cara/keadaan (Pel.34).', 'Bab 31–35 · Mondai 3 No.26', 'materi:book2:8:0'),
  (31, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>してください。</span><span class="arrange-chip"><b>③</b>とおりに</span><span class="arrange-chip"><b>④</b>せつめいしょ</span></div><small>Petunjuk arti: “Tolong lakukan sesuai petunjuk.”</small>', '["④→①→③→②","①→④→③→②","④→③→①→②","④→①→②→③"]'::jsonb, 0, 'Urutan yang benar: ④せつめいしょ→①の→③とおりに→②してください。 の menghubungkan kata benda dengan とおりに untuk menyatakan “sesuai dengan” (Pel.34).', 'Bab 31–35 · Mondai 3 No.27', 'materi:book2:8:0'),
  (31, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>あれば</span><span class="arrange-chip"><b>③</b>じかん</span><span class="arrange-chip"><b>④</b>いきます。</span></div><small>Petunjuk arti: “Kalau ada waktu, saya pergi.”</small>', '["③→①→②→④","①→③→②→④","③→②→①→④","③→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③じかん→①が→②あれば→④いきます。 が menandai subjek sebelum Kata Kerja bentuk ば yang menyatakan syarat umum (Pel.35).', 'Bab 31–35 · Mondai 3 No.28', 'materi:book2:9:0'),
  (31, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いいです。</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>はる</span><span class="arrange-chip"><b>④</b>へ</span><span class="arrange-chip"><b>⑤</b>きょうと</span><span class="arrange-chip"><b>⑥</b>なら</span><span class="arrange-chip"><b>⑦</b>いく</span></div><small>Petunjuk arti: “Kalau pergi ke Kyoto, musim semi bagus.”</small>', '["⑤→④→⑦→⑥→③→②→①","④→⑤→⑦→⑥→③→②→①","⑤→⑦→④→⑥→③→②→①","⑤→④→⑥→⑦→③→②→①"]'::jsonb, 0, 'Urutan yang benar: ⑤きょうと→④へ→⑦いく→⑥なら→③はる→②が→①いいです。 へ menandai tujuan sebelum なら, yang menyatakan saran berdasarkan topik yang disebut lawan bicara (Pel.35).', 'Bab 31–35 · Mondai 3 No.29', 'materi:book2:9:0'),
  (31, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>あめ</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>いきます。</span><span class="arrange-chip"><b>④</b>ふっても</span></div><small>Petunjuk arti: “Walaupun hujan, saya pergi.”</small>', '["①→②→④→③","②→①→④→③","①→④→②→③","①→②→③→④"]'::jsonb, 0, 'Urutan yang benar: ①あめ→②が→④ふっても→③いきます。 が menandai subjek sebelum Kata Kerja bentuk ても yang menyatakan hasil tetap berlaku (Pel.35).', 'Bab 31–35 · Mondai 3 No.30', 'materi:book2:9:0'),
  (31, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょう</span><span class="arrange-chip"><b>②</b>でかけない</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>つもりです。</span></div><small>Petunjuk arti: “Hari ini saya berniat tidak keluar.”</small>', '["①→③→②→④","③→①→②→④","①→②→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ①きょう→③は→②でかけない→④つもりです。 Bentuk ない dipakai sebelum つもりです untuk menyatakan niat TIDAK melakukan sesuatu (Pel.31).', 'Bab 31–35 · Mondai 4 No.31', 'materi:book2:5:0'),
  (31, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>ほうが</span><span class="arrange-chip"><b>③</b>いいです。</span><span class="arrange-chip"><b>④</b>おさけ</span><span class="arrange-chip"><b>⑤</b>のみすぎない</span></div><small>Petunjuk arti: “Sebaiknya jangan terlalu banyak minum alkohol.”</small>', '["④→①→⑤→②→③","①→④→⑤→②→③","④→⑤→①→②→③","④→①→②→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ④おさけ→①を→⑤のみすぎない→②ほうが→③いいです。 Kata Kerja bentuk ないほうがいいです menyatakan saran agar TIDAK melakukan sesuatu (Pel.32).', 'Bab 31–35 · Mondai 4 No.32', 'materi:book2:6:0'),
  (31, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>たばこ</span><span class="arrange-chip"><b>②</b>いみです。</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>いけない</span><span class="arrange-chip"><b>⑥</b>で</span><span class="arrange-chip"><b>⑦</b>という</span><span class="arrange-chip"><b>⑧</b>ここ</span><span class="arrange-chip"><b>⑨</b>すっては</span></div><small>Petunjuk arti: “Di sini artinya tidak boleh merokok.”</small>', '["⑧→⑥→④→①→③→⑨→⑤→⑦→②","⑥→⑧→④→①→③→⑨→⑤→⑦→②","⑧→④→⑥→①→③→⑨→⑤→⑦→②","⑧→⑥→①→④→③→⑨→⑤→⑦→②"]'::jsonb, 0, 'Urutan yang benar: ⑧ここ→⑥で→④は→①たばこ→③を→⑨すっては→⑤いけない→⑦という→②いみです。 Pola ～という意味です dipakai untuk menjelaskan arti dari suatu aturan atau larangan yang disebut sebelumnya (Pel.33).', 'Bab 31–35 · Mondai 4 No.33', 'materi:book2:7:0'),
  (31, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ごはん</span><span class="arrange-chip"><b>②</b>あとで</span><span class="arrange-chip"><b>③</b>べんきょうします。</span><span class="arrange-chip"><b>④</b>たべた</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Setelah makan, saya belajar.”</small>', '["①→⑤→④→②→③","⑤→①→④→②→③","①→④→⑤→②→③","①→⑤→②→④→③"]'::jsonb, 0, 'Urutan yang benar: ①ごはん→⑤を→④たべた→②あとで→③べんきょうします。 Kata Kerja bentuk たあとで menyatakan tindakan yang dilakukan SETELAH tindakan lain selesai (Pel.34).', 'Bab 31–35 · Mondai 4 No.34', 'materi:book2:8:0'),
  (31, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほうが</span><span class="arrange-chip"><b>②</b>よやくした</span><span class="arrange-chip"><b>③</b>はやく</span><span class="arrange-chip"><b>④</b>する</span><span class="arrange-chip"><b>⑤</b>りょこう</span><span class="arrange-chip"><b>⑥</b>なら</span><span class="arrange-chip"><b>⑦</b>いいです。</span></div><small>Petunjuk arti: “Kalau mau bepergian, sebaiknya cepat memesan.”</small>', '["⑤→④→⑥→③→②→①→⑦","④→⑤→⑥→③→②→①→⑦","⑤→⑥→④→③→②→①→⑦","⑤→④→③→⑥→②→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤りょこう→④する→⑥なら→③はやく→②よやくした→①ほうが→⑦いいです。 なら menyatakan saran berdasarkan topik yang disebut lawan bicara, diikuti pola たほうがいいです (Pel.35).', 'Bab 31–35 · Mondai 4 No.35', 'materi:book2:9:0'),
  (31, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'らいねん、にほんへ　りゅうがくする　つもりです。りょこうの　ひは、らいげつの　15にちの　よていです。<br><small>「よていです」は、どちらの　ことですか。</small>', '["りゅうがくすること","りょこうのひ","にほんへいくこと","らいねんのこと"]'::jsonb, 1, '予定です menyatakan RENCANA/JADWAL OBJEKTIF yang sudah ditentukan (tanggal perjalanan), berbeda dari つもりです yang menyatakan NIAT PRIBADI (rencana studi ke luar negeri) (Pel.31).', 'Bab 31–35 · Soal Cerita No.36', 'materi:book2:5:0'),
  (31, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'やさいを　もっと　たべた　ほうが　いいです。でも、おさけを　のみすぎない　ほうが　いいです。<br><small>すすめられている　ことは、なんですか。</small>', '["やさいをたべること","おさけをのむこと","おさけをのみすぎること","なにもたべないこと"]'::jsonb, 0, 'たほうがいいです menyarankan MELAKUKAN sesuatu (makan sayur), sedangkan ないほうがいいです menyarankan TIDAK melakukan (jangan minum berlebihan) — dua arah saran yang berlawanan (Pel.32).', 'Bab 31–35 · Soal Cerita No.37', 'materi:book2:6:0'),
  (31, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '「たちいりきんし」という　かんばんが　あります。これは「はいるな」という　いみです。<br><small>「たちいりきんし」は、なにを　しては　いけないという　いみですか。</small>', '["でること","はいること","とまること","みること"]'::jsonb, 1, '「立入禁止」berarti「入るな」(jangan masuk), bentuk larangan tegas Bentuk Kamus＋な, dijelaskan dengan pola という意味です (Pel.33).', 'Bab 31–35 · Soal Cerita No.38', 'materi:book2:7:0'),
  (31, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'はを　みがいた　あとで、ねます。せつめいしょの　とおりに、きかいを　くみたてます。<br><small>「とおりに」は、なにを　あらわしますか。</small>', '["じゅんばん（はやい・おそい）","ほうほう（どうやってするか）","じかん（いつするか）","ばしょ（どこでするか）"]'::jsonb, 1, 'とおりに menyatakan melakukan sesuatu SESUAI CONTOH/PETUNJUK (cara), berbeda dari あとで yang menyatakan URUTAN WAKTU (Pel.34).', 'Bab 31–35 · Soal Cerita No.39', 'materi:book2:8:0'),
  (31, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'じかんが　あれば、いきます。きょうとへ　いくなら、はるが　いいです。あめが　ふっても、いきます。<br><small>あめの　ひでも、いきますか。</small>', '["はい、いきます","いいえ、いきません","じかんがあれば、いきます","はるなら、いきます"]'::jsonb, 0, '「あめがふっても、いきます」menggunakan ても yang menyatakan hasil TETAP TERJADI meski syarat (hujan) terpenuhi, jadi jawabannya tetap pergi walau hujan (Pel.35).', 'Bab 31–35 · Soal Cerita No.40', 'materi:book2:9:0');
